  (() => {
    const key =
      appsmith.store.selectedSensor ||
      (GetLatestSimple.data && GetLatestSimple.data[0] && GetLatestSimple.data[0].SensorKey);

    if (!key) return [];

    return (GetSeriesSimple.data || [])
      .filter(r => r.SensorKey === key)
      .map(r => ({
        // legacy chart wants x as string/number (avoid Date objects)
        x: moment(r.Timestamp).format("YYYY-MM-DD HH:mm"),
        y: Number(r.Value)
      }));
  })()
}}

